package com.kovian.finance.asset.api; import com.kovian.finance.asset.domain.*; import com.kovian.finance.asset.repository.*; import com.kovian.finance.security.CurrentUser; import org.springframework.http.HttpStatus; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/assets") public class AssetController {final FinancialAssetRepository repo; AssetController(FinancialAssetRepository r){repo=r;} record Request(UUID ownerId,String name,String assetType,BigDecimal acquisitionValue,BigDecimal currentValue,AssetLiquidity liquidity){} @PostMapping public FinancialAsset create(@RequestBody Request r){UUID owner=CurrentUser.ownerId(); if(r.ownerId()!=null&&!owner.equals(r.ownerId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); if(r.name()==null||r.name().isBlank()||r.acquisitionValue()==null||r.acquisitionValue().signum()<0||r.currentValue()==null||r.currentValue().signum()<0||r.liquidity()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid asset request"); return repo.save(new FinancialAsset(owner,r.name(),r.assetType(),r.acquisitionValue(),r.currentValue(),r.liquidity()));} @GetMapping public List<FinancialAsset> list(@RequestParam(required=false) UUID ownerId){UUID owner=CurrentUser.ownerId(); if(ownerId!=null&&!owner.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); return repo.findByOwnerIdAndActiveTrue(owner);} @PatchMapping("/{id}/value") @Transactional public void update(@PathVariable UUID id,@RequestParam(required=false) UUID ownerId,@RequestBody BigDecimal value){UUID owner=CurrentUser.ownerId(); if(ownerId!=null&&!owner.equals(ownerId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Owner scope violation"); repo.findById(id).filter(a->a.getOwnerId().equals(owner)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Asset not found")).updateValue(value);}}